# -*- coding: utf-8 -*-
"""MANAPRINT — BINGO BALL · 7 boules · maquette Canva de Maeva (27/11/2026, « bingo_ball_canva_12_A4 »).
Reprise TELLE QUELLE : 12 cartons / feuille A4 PAYSAGE (4 x 3), traits de coupe en pointillés.
Chaque carton : BINGO BALL, 7 BOULES, les boules et la sphère de tirage (dessins Canva posés en
pochoir : en couleur, MANAPRINT les repeint avec les cases, les chiffres restent noirs),
une croix de 7 cases (N en haut, B I N G O au milieu, N en bas), le N°.
RÈGLE (celle de BINGO BALL, inchangée) : B 1-15 · I 16-30 · G 46-60 · O 61-75 ·
   les trois N (haut, centre, bas) : trois numéros différents de 31-45.   Crieur : 1 à 75.
Chiffres Helvetica 30 pt noirs, comme sur la maquette.
Le tout est réduit pour garder 6 mm de marge d'impression (Konica / Sharp)."""

import io, random
from reportlab.pdfgen import canvas
from reportlab.lib.pagesizes import A4, landscape
from reportlab.lib import colors

try:
    from generators import canva_masque as _masque
except Exception:
    import canva_masque as _masque

PAGE_W, PAGE_H = landscape(A4)
COLS, RANGS = 4, 3
CARTES_PAGE = COLS * RANGS                # 12
CELL_W, CELL_H = 210.4724, 198.4252
NOIR = colors.black
POLICE_NUM = "Helvetica"
TAILLE_NUM = 30
# (centre x, ligne de base) : N haut · B I N G O · N bas
CASES = [(105.232, 119.622), (24.730, 72.850), (64.980, 72.850), (105.232, 72.850), (145.484, 72.850),
         (185.736, 72.850), (105.232, 26.079)]
# (x, y, largeur, hauteur, n° du dessin) : boules en haut à gauche, sphère en haut à droite,
#                                          sphère en bas à gauche, boules en bas à droite
_IMGS = [(11.33858, 110.2677, 47.421, 39.68504, 0), (147.5086, 110.2677, 51.62529, 39.68504, 1),
         (11.33858, 16.72441, 51.62529, 39.68504, 1), (151.7129, 16.72441, 47.421, 39.68504, 0)]

MARGE_SURE = 6 * 72 / 25.4
ECHELLE = min((PAGE_W - 2 * MARGE_SURE) / PAGE_W, (PAGE_H - 2 * MARGE_SURE) / PAGE_H)
DECAL_X = (PAGE_W - PAGE_W * ECHELLE) / 2.0
DECAL_Y = (PAGE_H - PAGE_H * ECHELLE) / 2.0
_DEJA = set()


def _numeros(rng):
    t = None
    for _ in range(500):
        n = rng.sample(range(31, 46), 3)
        t = (n[0], rng.randint(1, 15), rng.randint(16, 30), n[1], rng.randint(46, 60), rng.randint(61, 75), n[2])
        if t not in _DEJA:
            break
    _DEJA.add(t)
    return t


def _txt(c, s, x, y, police, taille, col, centre=False):
    w = c.stringWidth(s, police, taille)
    t = c.beginText(x - w / 2.0 if centre else x, y); t.setFont(police, taille)
    t.setFillColor(col); t.textOut(s)
    c.drawText(t)


def _en_teinte():
    import sys
    for nom in ("app", "__main__"):
        m = sys.modules.get(nom)
        e = getattr(m, "_TEINTE_ETAT", None) if m else None
        if e is not None and getattr(e, "canva", False):
            return True
    return False


def _modele(c):
    if getattr(c, "_bingoball_modele", False):
        return
    import base64
    d = _DESSIN
    teinte = _en_teinte()
    if teinte:          # version couleur : les cases grises prennent aussi la couleur du carton
        d = d.replace(".45 .45 .45 RG", "0 0 0 RG")
    for k, v in (("{HB}", "Helvetica-Bold"), ("{H}", "Helvetica")):
        d = d.replace(k, c._doc.getInternalFontName(v))
    c.beginForm("BINGOBALL_CANVA", 0, 0, CELL_W, CELL_H)
    c._code.append("q\n0 g\n0 G")
    morceaux = d
    for i in range(len(_IMGS)):
        morceaux = morceaux.replace("@IMG%d@" % i, "\x00%d\x00" % i)
    for j, part in enumerate(morceaux.split("\x00")):
        if j % 2 == 1:
            i = int(part); x, y, w, h, k = _IMGS[i]
            _masque.poser(c, "BINGOBALL_IMG_%d" % k, base64.b64decode(_PNG[k]), x, y, w, h)
            if k == 1 and not teinte:      # la sphère est grise claire sur la maquette : gris en N&B
                for j in range(len(c._code) - 1, -1, -1):
                    if c._code[j] == "0 0 0 rg":
                        c._code[j] = ".55 .55 .55 rg"
                        break
        elif part:
            c._code.append(part)
    c._code.append("Q")
    c.endForm()
    c._bingoball_modele = True


def _billet(c, ox, oy, serie, nums, col):
    _modele(c)
    c.saveState()
    c.translate(ox, oy)
    c.doForm("BINGOBALL_CANVA")
    _txt(c, "N\u00b0 %06d" % serie, 9.637795, 183.685, "Helvetica-Bold", 5.2, colors.Color(.2, .2, .2))
    for (x, y), n in zip(CASES, nums):
        _txt(c, str(n), x, y, POLICE_NUM, TAILLE_NUM, col, centre=True)
    c.restoreState()


def generer_pdf(nb_cartes=None, nb_tickets=None, serie_start=1, theme="", couleur=True,
                nom_evenement="", titre_jeu="", couleur_perso="", date_lieu="",
                telephone="", page_start=1, evenement_id="", style="", motif="", **_ig):
    n_ = nb_cartes if nb_cartes is not None else nb_tickets
    n_ = max(1, int(n_ if n_ else CARTES_PAGE))
    buf = io.BytesIO()
    c = canvas.Canvas(buf, pagesize=(PAGE_W, PAGE_H), pageCompression=1)
    c.setTitle("BINGO BALL · 7 boules")
    rng = random.Random(int(serie_start) * 100003 + 2722)
    _DEJA.clear()
    serie = int(serie_start)
    faits = 0
    try:
        no_page = max(1, int(page_start))
    except Exception:
        no_page = 1
    while faits < n_:
        c.setFillColor(colors.Color(0.5, 0.5, 0.5)); c.setFont("Helvetica", 7)
        c.drawRightString(PAGE_W - DECAL_X, PAGE_H - DECAL_Y / 2.0 - 2.5, "page %d" % no_page)
        entete = "  ·  ".join(t for t in ((nom_evenement or "").strip(), (date_lieu or "").strip()) if t)
        if entete:
            c.setFillColor(NOIR); c.setFont("Helvetica-Bold", 7)
            c.drawCentredString(PAGE_W / 2.0, PAGE_H - DECAL_Y / 2.0 - 2.5, entete)
        c.saveState()
        c.translate(DECAL_X, DECAL_Y); c.scale(ECHELLE, ECHELLE)
        for idx in range(CARTES_PAGE):
            if faits >= n_:
                break
            ox = (idx % COLS) * CELL_W
            oy = (RANGS - 1 - idx // COLS) * CELL_H
            _billet(c, ox, oy, serie, _numeros(rng), NOIR)
            serie += 1
            faits += 1
        c.setStrokeColor(colors.Color(0.5, 0.5, 0.5)); c.setLineWidth(0.3); c.setDash(2, 2)
        for i in range(1, COLS):
            c.line(i * CELL_W, 0, i * CELL_W, RANGS * CELL_H)
        for j in range(1, RANGS):
            c.line(0, j * CELL_H, COLS * CELL_W, j * CELL_H)
        c.restoreState()
        c.showPage()
        no_page += 1
    c.save()
    buf.seek(0)
    return buf


